changeSet.sql:
UPDATE room_types SET standard_seat_count = 32, vip_seat_count = 32, couple_seat_count = 8 WHERE name = N'Phòng Nhỏ';
UPDATE room_types SET standard_seat_count = 40, vip_seat_count = 60, couple_seat_count = 10 WHERE name = N'Phòng Vừa';
UPDATE room_types SET standard_seat_count = 60, vip_seat_count = 180, couple_seat_count = 10 WHERE name = N'Phòng Lớn';

UPDATE rooms SET room_type_id = (SELECT room_type_id FROM room_types WHERE name = N'Phòng Lớn')
WHERE room_type_id = (SELECT room_type_id FROM room_types WHERE name = N'Phòng Tiêu Chuẩn');

UPDATE rooms SET room_type_id = NULL
WHERE room_type_id = (SELECT room_type_id FROM room_types WHERE name = N'Phòng Mini');

DELETE FROM room_types WHERE name IN (N'Phòng Tiêu Chuẩn', N'Phòng Mini');
